import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    df_c = df[df['row_kind'] == 'counted'].copy()
except Exception:
    df_c = df.copy()

try:
    metrics = ['earned_premium', 'claim_count', 'claim_amount']
    eda = {}
    for col in metrics:
        s = df_c[col].dropna()
        eda[col] = {
            "mean": float(s.mean()),
            "std": float(s.std()),
            "min": float(s.min()),
            "max": float(s.max()),
            "median": float(s.median()),
            "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception:
    pass

try:
    import numpy as np
    numeric_cols = ['earned_premium', 'claim_count', 'claim_amount']
    corr_dict = {}
    for i, c1 in enumerate(numeric_cols):
        for c2 in numeric_cols[i+1:]:
            pair = df_c[[c1, c2]].dropna()
            if len(pair) > 1:
                r = float(pair[c1].corr(pair[c2]))
                if abs(r) >= 0.2:
                    corr_dict[f"{c1}__{c2}"] = round(r, 4)
    result['correlations'] = corr_dict
except Exception:
    pass

try:
    segs = []
    seg_cols = ['line', 'region']
    metric_cols = ['earned_premium', 'claim_count', 'claim_amount']
    for seg in seg_cols:
        for met in metric_cols:
            grp = df_c.groupby(seg)[met].sum().reset_index()
            grp = grp.sort_values(met, ascending=False).head(10)
            segs.append({
                "segment_column": seg,
                "metric_column": met,
                "aggregation": "sum",
                "label": None,
                "results": [{"name": str(r[seg]), "value": float(r[met])} for _, r in grp.iterrows()]
            })
    for seg in seg_cols:
        grp = df_c.groupby(seg).agg(
            incurred=('claim_amount', 'sum'),
            premium=('earned_premium', 'sum')
        ).reset_index()
        grp['lr'] = grp['incurred'] / grp['premium'].replace(0, float('nan'))
        segs.append({
            "segment_column": seg,
            "metric_column": "claim_amount",
            "aggregation": "ratio",
            "label": "loss_ratio",
            "results": [{"name": str(r[seg]), "value": round(float(r['lr']), 4)} for _, r in grp.iterrows()]
        })
    result['segments'] = segs
except Exception:
    pass

try:
    import numpy as np
    anomalies = []
    skip_cols = ['policy_id']
    check_cols = ['earned_premium', 'claim_count', 'claim_amount']
    total_cap = 25
    for col in check_cols:
        if total_cap <= 0:
            break
        s = df_c[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo_t, hi_t = q1 - 3 * iqr, q3 + 3 * iqr
        flagged = s_t[(s_t < lo_t) | (s_t > hi_t)]
        pct = len(flagged) / len(s_t) if len(s_t) > 0 else 0
        if pct > 0.05:
            anomalies.append({
                "column": col,
                "row_index": None,
                "value": None,
                "expected_range": "heavy-tailed distribution",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme values are natural for this distribution and not individually flagged"
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_t) - shift)
            hi_orig = float(np.expm1(hi_t) - shift)
        else:
            lo_orig, hi_orig = float(lo_t), float(hi_t)
        exp_range = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
        col_cap = min(5, total_cap)
        for idx in flagged.index[:col_cap]:
            raw_val = float(df_c.loc[idx, col])
            s_val = s_t.loc[idx]
            if s_val > q3 + 5 * iqr or s_val < q1 - 5 * iqr:
                sev = "critical"
            elif s_val > q3 + 4 * iqr or s_val < q1 - 4 * iqr:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col,
                "row_index": int(idx),
                "value": raw_val,
                "expected_range": exp_range,
                "severity": sev,
                "explanation": f"{col} value {raw_val:.2f} lies outside expected range {exp_range}"
            })
            total_cap -= 1
    result['anomalies'] = anomalies
except Exception:
    pass

try:
    import numpy as np
    df_c2 = df_c.copy()
    df_c2['month'] = pd.to_datetime(df_c2['month'])
    df_c2['ym'] = df_c2['month'].dt.to_period('M')
    trends = []
    for met in ['earned_premium', 'claim_count', 'claim_amount']:
        mo = df_c2.groupby('ym')[met].sum().sort_index()
        if len(mo) >= 2:
            pct = float((mo.iloc[-1] - mo.iloc[-2]) / mo.iloc[-2] * 100) if mo.iloc[-2] != 0 else 0.0
            direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
            trends.append({"column": met, "period": "MoM", "direction": direction, "pct_change": round(pct, 4), "segment": None})
    result['trends'] = trends
except Exception:
    pass

try:
