import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

import numpy as np
from scipy import stats

counted = df[df['row_kind'] == 'counted'].copy()

# EDA
try:
    metric_cols = ['Paid to Date', 'Case Reserve', 'Incurred', 'Salvage Subrogation']
    for col in metric_cols:
        s = counted[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# Correlations
try:
    num_df = counted[metric_cols].dropna()
    for i, c1 in enumerate(metric_cols):
        for c2 in metric_cols[i+1:]:
            r = num_df[c1].corr(num_df[c2])
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception:
    pass

# Segmentation
try:
    seg_cols = ['Line of Business', 'Coverage', 'Claim Status']
    for seg in seg_cols:
        for metric in metric_cols:
            grp = counted.groupby(seg)[metric].sum().nlargest(10)
            result['segments'].append({
                'segment_column': seg, 'metric_column': metric,
                'aggregation': 'sum', 'label': None,
                'results': [{'name': str(k), 'value': round(float(v), 2)} for k, v in grp.items()]
            })
        cnt = counted.groupby(seg)['Claim Number'].nunique().nlargest(10)
        result['segments'].append({
            'segment_column': seg, 'metric_column': 'Claim Number',
            'aggregation': 'count', 'label': 'distinct_claims',
            'results': [{'name': str(k), 'value': int(v)} for k, v in cnt.items()]
        })
    # Severity by Line of Business
    sev = counted.groupby('Line of Business').apply(
        lambda x: x['Incurred'].sum() / x['Claim Number'].nunique() if x['Claim Number'].nunique() > 0 else 0
    ).nlargest(10)
    result['segments'].append({
        'segment_column': 'Line of Business', 'metric_column': 'Incurred',
        'aggregation': 'ratio', 'label': 'severity_incurred_per_claim',
        'results': [{'name': str(k), 'value': round(float(v), 2)} for k, v in sev.items()]
    })
    # Cat Event breakdown
    cat_inc = counted.groupby('Cat Event')['Incurred'].sum().nlargest(10)
    result['segments'].append({
        'segment_column': 'Cat Event', 'metric_column': 'Incurred',
        'aggregation': 'sum', 'label': None,
        'results': [{'name': str(k), 'value': round(float(v), 2)} for k, v in cat_inc.items()]
    })
    # Joint Line of Business | Claim Status
    joint = counted.groupby(['Line of Business', 'Claim Status'])['Incurred'].sum().nlargest(10)
    result['segments'].append({
        'segment_column': 'Line of Business|Claim Status', 'metric_column': 'Incurred',
        'aggregation': 'sum', 'label': None,
        'results': [{'name': f'{k[0]}|{k[1]}', 'value': round(float(v), 2)} for k, v in joint.items()]
    })
except Exception:
    pass

# Anomalies
try:
    anomaly_records = []
    total_cap = 25
    for col in metric_cols:
        if total_cap <= 0:
            break
        s = counted[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = max(0, -s.min())
        if abs(skew) > 2:
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo_t, hi_t = q1 - 3 * iqr, q3 + 3 * iqr
        mask = (s_t < lo_t) | (s_t > hi_t)
        flagged_frac = mask.sum() / len(s_t)
        if flagged_frac > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} flags >{flagged_frac*100:.1f}% of values as extreme; heavy-tailed natural distribution, not anomalies'
            })
            continue
        if abs(skew) > 2:
            lo_orig = np.expm1(lo_t) - shift
            hi_orig = np.expm1(hi_t) - shift
        else:
            lo_orig, hi_orig = lo_t, hi_t
        extreme_idx = s_t[mask].index
        col_cap = min(len(extreme_idx), total_cap)
        for idx in extreme_idx[:col_cap]:
            val = float(counted.loc[idx, col])
            s_val = s_t.loc[idx]
            if s_val > q3 + 5 * iqr:
                sev = 'critical'
            elif s_val > q3 + 4 * iqr:
                sev = 'high'
            elif s_val > q3 + 3 * iqr or s_val < q1 - 3 * iqr:
                sev = 'medium'
            else:
                sev = 'low'
            exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {val} lies outside expected range {exp_range}'
            })
