        lapsed = x['Term'][x['Renewal Status'].str.lower().isin(['lapsed', 'lapse', 'non-renewed', 'not renewed', 'no', 'n', '0'])].nunique()
        denom = renewed + lapsed
        return renewed / denom if denom > 0 else float('nan')
    ret_grp = df_counted.groupby('Line of Business').apply(retention)
    result['segments'].append({
