            elif val_t > q3 + 4 * iqr or val_t < q1 - 4 * iqr:
                sev = 'high'
            else:
                sev = 'medium'
            anom_records.append({
                'column': col, 'row_index': int(idx), 'value': float(val),
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {float(val):.2f} lies outside expected range {exp_range}'
            })
            if len(anom_records) >= 25:
                break
        if len(anom_records) >= 25:
            break
    result['anomalies'] = anom_records[:25]
except Exception:
    pass

# TRENDS
try:
    counted['loss_month'] = counted['Loss Date'].dt.to_period('M')
    monthly = counted.groupby('loss_month').agg(
        incurred_sum=('Incurred', 'sum'),
        paid_sum=('Paid to Date', 'sum'),
        reserve_sum=('Case Reserve', 'sum')
    ).sort_index()
    if len(monthly) >= 2:
        for col_key, col_name in [('incurred_sum', 'Incurred'), ('paid_sum', 'Paid to Date'), ('reserve_sum', 'Case Reserve')]:
            vals = monthly[col_key].values
            pct = float((vals[-1] - vals[-2]) / vals[-2] * 100) if vals[-2] != 0 else 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': col_name, 'period': 'MoM', 'direction': direction,
                'pct_change': round(pct, 2), 'segment': None
            })
        # YoY by accident year
        counted['loss_year'] = counted['Loss Date'].dt.year
        yearly = counted.groupby('loss_year')['Incurred'].sum().sort_index()
        if len(yearly) >= 2:
            yvals = yearly.values
            ypct = float((yvals[-1] - yvals[-2]) / yvals[-2] * 100) if yvals[-2] != 0 else 0.0
            ydir = 'up' if ypct > 1 else ('down' if ypct < -1 else 'flat')
            result['trends'].append({
                'column': 'Incurred', 'period': 'YoY', 'direction': ydir,
                'pct_change': round(ypct, 2), 'segment': None
            })
except Exception:
    pass

# FORECASTING (simple linear extrapolation on monthly incurred)
try:
    if len(monthly) >= 6:
        x = np.arange(len(monthly))
        y = monthly['incurred_sum'].values
        slope, intercept, _, _, _ = stats.linregress(x, y)
        next_periods = 3
        for i in range(1, next_periods + 1):
            xi = len(monthly) - 1 + i
            period_label = str(monthly.index[-1] + i)
            result['forecast_points'].append({
                'period': period_label,
                'value': round(float(intercept + slope * xi), 2)
            })
except Exception:
    pass

result['assumptions'] = [
    "Only 'counted' rows used; superseded valuations excluded per domain rules.",
    "Severity = total Incurred / distinct Claim Numbers within each segment.",
    "Trends use Loss Date month; YoY compares last two full accident years.",
    "Forecast is a 3-month linear extrapolation on monthly incurred totals.",
    "Anomaly detection uses 3×IQR boundary; log1p applied for skewed columns."
]
